def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction
    from math import gcd

    jump = {a: b for a, b in jumps}
    destination = list(range(n + 1))

    for start in jump:
        path = []
        cell = start
        while cell in jump and destination[cell] == cell:
            path.append(cell)
            cell = jump[cell]
        end = destination[cell]
        for cell in path:
            destination[cell] = end

    transitions = {}
    reachable = {0}
    queue = deque([0])

    while queue:
        cell = queue.popleft()
        counts = {}
        for roll in range(1, m + 1):
            landed = cell + roll
            if landed > n:
                landed = 2 * n - landed
            landed = destination[landed]
            counts[landed] = counts.get(landed, 0) + 1
            if landed != n and landed not in reachable:
                reachable.add(landed)
                queue.append(landed)
        transitions[cell] = counts

    reverse = [[] for _ in range(n + 1)]
    for cell, counts in transitions.items():
        for target in counts:
            reverse[target].append(cell)

    can_finish = {n}
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                queue.append(previous)

    if not reachable <= can_finish:
        return None

    states = sorted(reachable)
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)
    matrix = [[0] * (size + 1) for _ in range(size)]

    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for target, count in transitions[cell].items():
            if target != n:
                matrix[i][index[target]] -= count

    for col in range(size):
        pivot_row = next(row for row in range(col, size) if matrix[row][col])
        matrix[col], matrix[pivot_row] = matrix[pivot_row], matrix[col]
        pivot = matrix[col][col]

        for row in range(col + 1, size):
            factor = matrix[row][col]
            if factor == 0:
                continue
            common = gcd(abs(pivot), abs(factor))
            multiplier = pivot // common
            subtractor = factor // common
            for k in range(col + 1, size + 1):
                matrix[row][k] = (
                    multiplier * matrix[row][k] - subtractor * matrix[col][k]
                )
            matrix[row][col] = 0
            common = 0
            for value in matrix[row][col + 1:]:
                common = gcd(common, abs(value))
            if common > 1:
                for k in range(col + 1, size + 1):
                    matrix[row][k] //= common

    solution = [Fraction(0) for _ in range(size)]
    for row in range(size - 1, -1, -1):
        value = Fraction(matrix[row][size])
        for col in range(row + 1, size):
            value -= matrix[row][col] * solution[col]
        solution[row] = value / matrix[row][row]

    result = solution[index[0]]
    return [result.numerator, result.denominator]
